  'files/dependency-cruiser.cjs':
    "module.exports = {\n  extends: 'dependency-cruiser/configs/recommended-strict',\n  options: {\n    tsConfig: { fileName: 'tsconfig.json' },\n    tsPreCompilationDeps: true,\n    exclude: { path: '\\\\.gen\\\\.ts$|(^|/)env\\\\.d\\\\.ts$' },\n    enhancedResolveOptions: {\n      exportsFields: ['exports'],\n      conditionNames: ['import', 'require', 'node', 'types', 'default'],\n    },\n  },\n};\n",
  'files/github-chromatic.yml':
    'name: chromatic\n\non:\n  pull_request:\n    types: [opened, synchronize, reopened]\n  push:\n    branches: [main]\n\npermissions:\n  contents: read\n\njobs:\n  screens:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: step-security/harden-runner@bf7454d06d71f1098171f2acdf0cd4708d7b5920 # v2.20.0\n        with:\n          egress-policy: audit\n      # Chromatic compares each build against the one before it, so it reads\n      # the whole history rather than the tip.\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7\n        with:\n          fetch-depth: 0\n          persist-credentials: false\n      - uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2\n        with:\n          bun-version-file: package.json\n      - run: bun install --frozen-lockfile\n      - run: bunx playwright install --with-deps chromium\n      - run: bun run test:browser\n      - run: bunx chromatic --playwright --exit-zero-on-changes\n        env:\n          CHROMATIC_PROJECT_TOKEN: ${{ secrets.CHROMATIC_PROJECT_TOKEN }}\n',
  'files/github-ci.yml':
    "name: ci\n\non:\n  pull_request:\n    types: [opened, synchronize, reopened]\n  push:\n    branches: [main]\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: ci-${{ github.ref }}\n  cancel-in-progress: ${{ github.ref != 'refs/heads/main' }}\n\njobs:\n  check:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: step-security/harden-runner@bf7454d06d71f1098171f2acdf0cd4708d7b5920 # v2.20.0\n        with:\n          egress-policy: audit\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7\n        with:\n          persist-credentials: false\n      - uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2\n        with:\n          bun-version-file: package.json\n      - uses: jdx/mise-action@c37c93293d6b742fc901e1406b8f764f6fb19dac # v2\n      - run: bun install --frozen-lockfile\n      - run: bun run fmt:check\n      - run: bun run lint\n      - run: bun run check-types\n      - run: bun run lint:boundaries\n      - run: bun run lint:graph\n      - run: bun run lint:ui\n      - run: bun run lint:env\n      - run: bun run lint:bdd\n      - run: bun run lint:dead\n      - run: bun run lint:dup\n      - run: bun run lint:spell\n      - run: bun run lint:workflows\n      - run: bun run lint:secrets\n      - run: bun run test\n      - run: bun run test:integration\n      - run: bun run build\n\n  browser:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: step-security/harden-runner@bf7454d06d71f1098171f2acdf0cd4708d7b5920 # v2.20.0\n        with:\n          egress-policy: audit\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7\n        with:\n          persist-credentials: false\n      - uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2\n        with:\n          bun-version-file: package.json\n      - run: bun install --frozen-lockfile\n      - run: bunx playwright install --with-deps chromium\n      - run: bun run test:component\n      - run: bun run test:browser\n\n  mutation:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: step-security/harden-runner@bf7454d06d71f1098171f2acdf0cd4708d7b5920 # v2.20.0\n        with:\n          egress-policy: audit\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7\n        with:\n          persist-credentials: false\n      - uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2\n        with:\n          bun-version-file: package.json\n      - run: bun install --frozen-lockfile\n      - uses: actions/cache@0057852bfaa89a56745cba8c7296529d2fc39830 # v4.3.0\n        with:\n          path: reports/stryker-incremental.json\n          key: mutation-${{ github.sha }}\n          restore-keys: |\n            mutation-\n      - name: Retest what changed since the baseline\n        run: bun run test:mutation -- --incremental\n\n  prose:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: step-security/harden-runner@bf7454d06d71f1098171f2acdf0cd4708d7b5920 # v2.20.0\n        with:\n          egress-policy: audit\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7\n        with:\n          persist-credentials: false\n      - uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2\n        with:\n          bun-version-file: package.json\n      - uses: jdx/mise-action@c37c93293d6b742fc901e1406b8f764f6fb19dac # v2\n      - run: bun install --frozen-lockfile\n      - run: bun run lint:prose\n",
